import './Navbar.css';
import navList from '../../data/navBar.json';

function NavbarItems() {
    return (
        <div className="navbar-list">
            <ul>
                {navList.map((item, index) => (
                    <li className={`${item.active ? "active" : ''}`} key={index}>
                        <a href="#">
                            <i className={`fas ${item.icon}`} />
                            <span>{item.type}</span>
                        </a>
                    </li>
                ))}
            </ul>
        </div>
    );
}

export default NavbarItems;
